import { useFetch } from "@hyper-fetch/react";

const UserList = () => {
  const { data, loading } = useFetch(
    getUsers.setData({
      query: `{ users { id name } }`,
    }),
  );

  if (loading) return <p>Loading...</p>;
  return (
    <ul>
      {data?.users.map((u) => (
        <li key={u.id}>{u.name}</li>
      ))}
    </ul>
  );
};
